document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("drywall-form"),n=document.getElementById("drywall-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const t=parseFloat(document.getElementById("drywall-walls").value),s=parseFloat(document.getElementById("drywall-ceiling").value),a=parseFloat(document.getElementById("drywall-doors").value),o=parseFloat(document.getElementById("drywall-windows").value),[l,p]=document.getElementById("drywall-thickness").value.split(",").map(Number),[r,i]=document.getElementById("drywall-size").value.split(",").map(Number),d=parseFloat(document.getElementById("drywall-waste").value);if(t<=0&&s<=0)return n.textContent="Please enter wall area and/or ceiling area.",void 0;const c=21*a,u=15*o,h=Math.max(0,t-c-u),g=h+s,$=g/r,m=$*(1+d),w=Math.ceil(m),v=g/1e3*3,y=Math.ceil(v/5),F=1.2*g,f=Math.ceil(F/500),x=.005*h+.007*s,b=Math.ceil(x),M=.5*(4*Math.sqrt(g)),E=Math.ceil(M/8),I=w*p,T=20*y,D=10*f,q=8*b,B=3*E,C=I+T+D+q+B,S=g/100,L=g/50,k=S+L,z=65*k,H=Math.ceil(g/32),N=Math.ceil(g/48),A=(H-N)*p;n.innerHTML=`\n        <div class="result-section">\n          <h4>Area Calculations:</h4>\n          <p>Wall area: ${t} sq ft</p>\n          <p>Ceiling area: ${s} sq ft</p>\n          <p>Less doors: ${c} sq ft (${a} doors)</p>\n          <p>Less windows: ${u} sq ft (${o} windows)</p>\n          <p><strong>Net area to cover: ${g} sq ft</strong></p>\n        </div>\n        \n        <div class="result-sheets">\n          <h4>Drywall Sheets:</h4>\n          <p><strong>${w} sheets</strong> (${r} sq ft each)</p>\n          <p>Base requirement: ${$.toFixed(1)} sheets</p>\n          <p>Waste factor: ${100*d}% (${(m-$).toFixed(1)} extra)</p>\n          <p>Sheet size: 4×${i} (${l}" thick)</p>\n          <p>Coverage: ${(w*r).toFixed(0)} sq ft total</p>\n        </div>\n        \n        <div class="result-compound">\n          <h4>Joint Compound & Tape:</h4>\n          <p><strong>${y} buckets</strong> joint compound (5-gallon)</p>\n          <p>Total compound: ${v.toFixed(1)} gallons needed</p>\n          <p><strong>${f} rolls</strong> drywall tape (500 ft rolls)</p>\n          <p>Linear feet of tape: ${F.toFixed(0)} ft</p>\n        </div>\n        \n        <div class="result-hardware">\n          <h4>Fasteners & Accessories:</h4>\n          <p><strong>${b} boxes</strong> drywall screws (1 lb boxes)</p>\n          <p>Screw length: ${.5===l?'1-1/4"':.625===l?'1-5/8"':'1-1/8"'}</p>\n          <p><strong>${E} pieces</strong> corner bead (8 ft lengths)</p>\n          <p>Corner bead total: ${M.toFixed(0)} linear feet</p>\n        </div>\n        \n        <div class="result-costs">\n          <h4>Material Costs:</h4>\n          <p>Drywall sheets: $${I.toFixed(0)} (${w} @ $${p})</p>\n          <p>Joint compound: $${T.toFixed(0)} (${y} buckets)</p>\n          <p>Tape: $${D.toFixed(0)} (${f} rolls)</p>\n          <p>Screws: $${q.toFixed(0)} (${b} boxes)</p>\n          <p>Corner bead: $${B.toFixed(0)} (${E} pieces)</p>\n          <p><strong>Total materials: $${C.toFixed(0)}</strong></p>\n        </div>\n        \n        <div class="result-labor">\n          <h4>Labor Estimates:</h4>\n          <p>Hanging time: ${S.toFixed(1)} hours</p>\n          <p>Finishing time: ${L.toFixed(1)} hours</p>\n          <p>Total labor: ${k.toFixed(1)} hours</p>\n          <p>Professional labor: $${z.toFixed(0)}</p>\n          <p><strong>Total project: $${(C+z).toFixed(0)}</strong></p>\n        </div>\n        \n        <div class="result-comparison">\n          <h4>Sheet Size Comparison:</h4>\n          <p>4×8 sheets needed: ${H}</p>\n          <p>4×12 sheets needed: ${N}</p>\n          <p>4×12 advantage: ${H-N} fewer sheets</p>\n          ${A>0?`<p>💰 Savings with 4×12: $${A.toFixed(0)}</p>`:""}\n        </div>\n        \n        <div class="result-timeline">\n          <h4>Installation Timeline:</h4>\n          <p><strong>Day 1:</strong> Hang all drywall sheets</p>\n          <p><strong>Day 2:</strong> Tape all seams (first coat)</p>\n          <p><strong>Day 3:</strong> Second coat of compound</p>\n          <p><strong>Day 4:</strong> Final coat and touch-ups</p>\n          <p><strong>Day 5:</strong> Sand smooth and prime</p>\n          <p><em>Allow 24 hours drying between coats</em></p>\n        </div>\n        \n        <div class="result-tools">\n          <h4>Tools Needed:</h4>\n          <p>🔧 Drywall screw gun or drill</p>\n          <p>📐 T-square and utility knife</p>\n          <p>🪚 Drywall saw or router</p>\n          <p>🔨 Hammer and pry bar</p>\n          <p>📏 Measuring tape and pencil</p>\n          <p>🎨 Mud pan and knives (6", 10", 12")</p>\n        </div>\n        \n        <div class="result-tips">\n          <h4>Installation Tips:</h4>\n          <p>📋 Plan sheet layout to minimize waste</p>\n          <p>🏠 Install ceilings first, then walls</p>\n          <p>🔧 Use proper screw spacing and depth</p>\n          <p>💧 Keep compound covered between coats</p>\n          <p>🌡️ Maintain 55-70°F for proper drying</p>\n        </div>\n      `})});